INSERT INTO posts (user_id, body, theme, is_pinned, status, created_at) VALUES ((SELECT id FROM users WHERE email = 'admin@ndoclub.local'), 'Bem-vindos ao No Days Off Club! Aqui a regra é simples: constância. Faça seu check-in todo dia, treine, poste e suba no ranking. No fim do mês os melhores ganham brindes.', NULL, 1, 'visible', NOW() - INTERVAL 6 HOUR);
