INSERT INTO posts (user_id, body, theme, is_pinned, status, created_at) VALUES ((SELECT id FROM users WHERE email = 'bruno.teste@exemplo.com'), 'Minha marmita da semana pronta. Frango, batata-doce e brócolis. Domingo de preparo é sagrado.', 'Domingo de preparo', 0, 'visible', NOW() - INTERVAL 9 HOUR);
INSERT INTO posts (user_id, body, theme, is_pinned, status, created_at) VALUES ((SELECT id FROM users WHERE email = 'elisa.teste@exemplo.com'), 'Hoje fechei 8 km sem parar. Faltam 2 km para a meta de 10!', NULL, 0, 'visible', NOW() - INTERVAL 3 HOUR);
INSERT INTO posts (user_id, body, theme, is_pinned, status, created_at) VALUES ((SELECT id FROM users WHERE email = 'diego.teste@exemplo.com'), 'Quem tem dica de café da manhã rápido? Acordo em cima da hora.', NULL, 0, 'visible', NOW() - INTERVAL 4 HOUR);
INSERT INTO posts (user_id, body, theme, is_pinned, status, created_at) VALUES ((SELECT id FROM users WHERE email = 'gabi.teste@exemplo.com'), 'Semana de meta batida: 5 treinos e todos os check-ins.', 'Quinta de vitória', 0, 'visible', NOW() - INTERVAL 12 HOUR);
